#include <bits/stdc++.h>

using namespace std;
const int c=200005;
int t, n, up[c];
bool parity[c], vis[c], no_sol;
vector<int> edges[c];
void dfs(int a) {
    vis[a]=true;
    int cnt[2]={0, 0};
    for (auto x:edges[a]) {
        if (!vis[x]) {
            up[x]=a;
            dfs(x);
            cnt[parity[x]]++;
        }
    }
    if (a!=1) {
        if (parity[a]=(cnt[0]>=cnt[1]));
        cnt[parity[a]]++;
    }
    if (cnt[1]-cnt[0]<0 || cnt[1]-cnt[0]>1) {
        no_sol=1;
    }
}
void solve(int a) {
    vector<int> p[2];
    for (auto x:edges[a]) {
        if (x!=up[a]) {
            p[parity[x]].push_back(x);
        } else {
            p[parity[a]].push_back(a);
        }
    }
    int si=edges[a].size(), id=si%2;
    for (int i=0; i<si; i++) {
        int val=p[id].back();
        if (val==a) {
            cout << a << " " << up[a] << "\n";
        } else {
            solve(val);
        }
        p[id].pop_back();
        id=1-id;
    }

}
int main()
{
    ios_base::sync_with_stdio(false);
    cin >> t;
    for (int test=0; test<t; test++) {
        cin >> n;
        for (int i=1; i<n; i++) {
            int a, b;
            cin >> a >> b;
            edges[a].push_back(b), edges[b].push_back(a);
        }
        dfs(1);
        if (no_sol) {
            cout << "NO\n";
        } else {
            cout << "YES\n";
            solve(1);
        }

        for (int i=1; i<=n; i++) {
            parity[i]=0, up[i]=0, vis[i]=0;
            edges[i].clear();
        }
        no_sol=0;
    }
    return 0;
}

